def transform(grid):
    from collections import Counter
    g = np.array(grid)
    bg = background(g)
    objs = objects(g, bg=bg, diagonal=True)
    keys = [tuple(map(tuple, (o["grid"] != bg).astype(int))) for o in objs]
    cnt = Counter(keys)
    out = g.copy()
    # stage 1: objects whose shape appears more than once -> colour 1
    for o, k in zip(objs, keys):
        if cnt[k] > 1:
            for (y, x) in o["cells"]:
                out[y, x] = 1
    emit(out, "Objects whose exact shape occurs more than once are recoloured 1.")
    # stage 2: unique-shape objects -> colour 2
    for o, k in zip(objs, keys):
        if cnt[k] == 1:
            for (y, x) in o["cells"]:
                out[y, x] = 2
    emit(out, "The object(s) with a unique shape are recoloured 2.")
    return out
